class 橘猫:
    def 叫声(self):
        return "{s1}"


class 狸花猫:
    def 叫声(self):
        return "{s2}"


class 三花猫:
    def 叫声(self):
        return "{s3}"


def 领养一只(花色):
    if 花色 == "橘":
        return 橘猫()
    if 花色 == "狸花":
        return 狸花猫()
    return 三花猫()


for 花色 in ["橘", "狸花", "花", "三花"]:
    print(花色, "->", 领养一只(花色).叫声())
